          }
        },
        {
          "text": "Extract structured financial data from this document. Return ONLY valid JSON matching this schema:\n{\n  \"expenseDate\": \"YYYY-MM-DD or null\",\n  \"vendor\": \"string or null\",\n  \"invoiceNumber\": \"string or null\",\n  \"description\": \"string or null\",\n  \"amount\": \"decimal string (e.g. '120.50') or null\",\n  \"currency\": \"3-letter currency code or null\",\n  \"taxAmount\": \"decimal string or null\",\n  \"subtotalAmount\": \"decimal string or null\",\n  \"category\": \"personnel | travel | equipment | software | events | operational | uncategorized\",\n  \"confidence\": {\n    \"expenseDate\": 0.0 to 1.0,\n    \"vendor\": 0.0 to 1.0,\n    \"amount\": 0.0 to 1.0,\n    \"currency\": 0.0 to 1.0\n  },\n  \"validationIssues\": []\n}\nRules: Never fabricate values. Use null for missing fields. Do not convert currencies. If subtotal and tax are present, verify they match total."
        }
      ]
    }
  ],
  "generationConfig": {
    "responseMimeType": "application/json",
    "temperature": 0.1
