parameters.jsCode:
const response = $input.item.json;
const prev = $('Check Request Valid').first().json;

let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini API returned an invalid or empty response structure.');
}

let data = {};
try {
  data = JSON.parse(rawText.trim());
} catch (e) {
  throw new Error('Failed to parse Gemini output as JSON: ' + rawText.slice(0, 100));
}

const issues = Array.isArray(data.validationIssues) ? [...data.validationIssues] : [];

// 1. Sanitize & Validate Vendor
let vendor = typeof data.vendor === 'string' && data.vendor.trim() ? data.vendor.trim().slice(0, 255) : null;
if (!vendor) {
  issues.push({ code: 'MISSING_VENDOR', message: 'Vendor name could not be identified', severity: 'warning', field: 'vendor' });
}

// 2. Invoice Number
let invoiceNumber = typeof data.invoiceNumber === 'string' && data.invoiceNumber.trim() ? data.invoiceNumber.trim().slice(0, 100) : null;
if (!invoiceNumber) {
  issues.push({ code: 'MISSING_INVOICE_NUMBER', message: 'Invoice number was not found', severity: 'warning', field: 'invoiceNumber' });
}

// 3. Description
let description = typeof data.description === 'string' && data.description.trim() ? data.description.trim().slice(0, 1000) : null;

// 4. Validate Real Calendar Date (YYYY-MM-DD)
let expenseDate = null;
if (typeof data.expenseDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.expenseDate.trim())) {
  const parts = data.expenseDate.trim().split('-');
  const y = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10);
  const d = parseInt(parts[2], 10);
  const dateObj = new Date(Date.UTC(y, m - 1, d));
  if (dateObj.getUTCFullYear() === y && dateObj.getUTCMonth() === m - 1 && dateObj.getUTCDate() === d) {
    expenseDate = data.expenseDate.trim();
  } else {
    issues.push({ code: 'INVALID_CALENDAR_DATE', message: `Date '${data.expenseDate}' is not a valid calendar date`, severity: 'warning', field: 'expenseDate' });
  }
} else {
  issues.push({ code: 'MISSING_OR_INVALID_DATE', message: 'Missing or invalid YYYY-MM-DD date', severity: 'warning', field: 'expenseDate' });
}

// 5. Amount & Bounds
let amount = null;
let parsedAmount = null;
if (data.amount !== null && data.amount !== undefined && String(data.amount).trim() !== '') {
  let cleanAmount = String(data.amount).trim().replace(/^["']|["']$/g, '');
  cleanAmount = cleanAmount.replace(/^(\$|€|£|¥|US\$|LE|EGP|AED|SAR)\s*/i, '');
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(cleanAmount)) {
    cleanAmount = cleanAmount.replace(/,/g, '');
  }
  if (/^-?\d+(\.\d+)?$/.test(cleanAmount)) {
    parsedAmount = Number(cleanAmount);
    if (isNaN(parsedAmount)) {
      issues.push({ code: 'INVALID_AMOUNT', message: 'Total amount is not a valid number', severity: 'error', field: 'amount' });
    } else if (parsedAmount <= 0) {
      amount = parsedAmount.toFixed(2);
      issues.push({ code: parsedAmount === 0 ? 'ZERO_AMOUNT' : 'NEGATIVE_AMOUNT', message: 'Total amount must be strictly positive', severity: 'error', field: 'amount' });
    } else {
      amount = parsedAmount.toFixed(2);
    }
  } else {
    issues.push({ code: 'INVALID_AMOUNT', message: 'Total amount format is invalid', severity: 'error', field: 'amount' });
  }
} else {
  issues.push({ code: 'MISSING_AMOUNT', message: 'Total amount was not found', severity: 'error', field: 'amount' });
}

// 6. Currency Normalization
const currencyMap = { '$': 'USD', 'US$': 'USD', '€': 'EUR', '£': 'GBP', '¥': 'JPY', 'EGP': 'EGP', 'LE': 'EGP', 'AED': 'AED', 'SAR': 'SAR', 'CAD': 'CAD', 'AUD': 'AUD', 'CHF': 'CHF' };
let currency = null;
if (typeof data.currency === 'string' && data.currency.trim()) {
  const rawCurr = data.currency.trim();
  const mapped = currencyMap[rawCurr] || currencyMap[rawCurr.toUpperCase()];
  if (mapped) {
    currency = mapped;
  } else {
    const upperCurr = rawCurr.toUpperCase().slice(0, 10);
    if (/^[A-Z]{3}$/.test(upperCurr)) {
      currency = upperCurr;
    } else {
      currency = upperCurr;
      issues.push({ code: 'NON_STANDARD_CURRENCY', message: `Currency '${rawCurr}' is non-standard`, severity: 'warning', field: 'currency' });
    }
  }
} else {
  issues.push({ code: 'MISSING_CURRENCY', message: 'Currency code was not found', severity: 'error', field: 'currency' });
}

// 7. Tax Amount
let taxAmount = null;
let parsedTax = null;
if (data.taxAmount !== null && data.taxAmount !== undefined && String(data.taxAmount).trim() !== '') {
  let cleanTax = String(data.taxAmount).trim().replace(/^["']|["']$/g, '');
  cleanTax = cleanTax.replace(/^(\$|€|£|¥|US\$|LE|EGP|AED|SAR)\s*/i, '');
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(cleanTax)) {
    cleanTax = cleanTax.replace(/,/g, '');
  }
  if (/^-?\d+(\.\d+)?$/.test(cleanTax)) {
    parsedTax = Number(cleanTax);
    if (isNaN(parsedTax)) {
      issues.push({ code: 'INVALID_TAXAMOUNT', message: 'Tax amount is not a valid number', severity: 'error', field: 'taxAmount' });
    } else if (parsedTax < 0) {
      taxAmount = parsedTax.toFixed(2);
      issues.push({ code: 'NEGATIVE_TAXAMOUNT', message: 'Tax amount cannot be negative', severity: 'error', field: 'taxAmount' });
    } else {
      taxAmount = parsedTax.toFixed(2);
      if (parsedAmount !== null && parsedTax > parsedAmount) {
        issues.push({ code: 'TAX_EXCEEDS_TOTAL', message: 'Tax amount exceeds total amount', severity: 'error', field: 'taxAmount' });
      }
    }
  } else {
    issues.push({ code: 'INVALID_TAXAMOUNT', message: 'Tax amount format is invalid', severity: 'error', field: 'taxAmount' });
  }
}

// 8. Subtotal Amount & Arithmetic Reconciliation
let subtotalAmount = null;
let parsedSubtotal = null;
if (data.subtotalAmount !== null && data.subtotalAmount !== undefined && String(data.subtotalAmount).trim() !== '') {
  let cleanSub = String(data.subtotalAmount).trim().replace(/^["']|["']$/g, '');
  cleanSub = cleanSub.replace(/^(\$|€|£|¥|US\$|LE|EGP|AED|SAR)\s*/i, '');
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(cleanSub)) {
    cleanSub = cleanSub.replace(/,/g, '');
  }
  if (/^-?\d+(\.\d+)?$/.test(cleanSub)) {
    parsedSubtotal = Number(cleanSub);
    if (isNaN(parsedSubtotal)) {
      issues.push({ code: 'INVALID_SUBTOTALAMOUNT', message: 'Subtotal amount is not a valid number', severity: 'error', field: 'subtotalAmount' });
    } else if (parsedSubtotal < 0) {
      subtotalAmount = parsedSubtotal.toFixed(2);
      issues.push({ code: 'NEGATIVE_SUBTOTALAMOUNT', message: 'Subtotal amount cannot be negative', severity: 'error', field: 'subtotalAmount' });
    } else {
      subtotalAmount = parsedSubtotal.toFixed(2);
    }
  } else {
    issues.push({ code: 'INVALID_SUBTOTALAMOUNT', message: 'Subtotal amount format is invalid', severity: 'error', field: 'subtotalAmount' });
  }
}

if (parsedAmount !== null && parsedTax !== null && parsedSubtotal !== null) {
  const calcTotal = parsedSubtotal + parsedTax;
  if (Math.abs(calcTotal - parsedAmount) > 0.02) {
    issues.push({ code: 'ARITHMETIC_MISMATCH', message: `Subtotal (${subtotalAmount}) + Tax (${taxAmount}) = ${calcTotal.toFixed(2)} does not match Total (${amount}) within 0.02 tolerance`, severity: 'warning', field: 'amount' });
  }
}

// 9. Category
const validCategories = ['personnel', 'travel', 'equipment', 'software', 'events', 'operational', 'uncategorized'];
let category = 'uncategorized';
if (typeof data.category === 'string' && validCategories.includes(data.category.trim().toLowerCase())) {
  category = data.category.trim().toLowerCase();
} else {
  issues.push({ code: 'UNCATEGORIZED_EXPENSE', message: 'Category defaulted to uncategorized', severity: 'warning', field: 'category' });
}

// 10. Deduplicate issues
const seenIssueKeys = new Set();
const uniqueIssues = issues.filter(iss => {
  const key = `${iss.code}_${iss.field || ''}_${iss.message}`;
  if (seenIssueKeys.has(key)) return false;
  seenIssueKeys.add(key);
  return true;
});

// 11. Initial Status
let validationStatus = 'valid';
const hasErrors = uniqueIssues.some(i => i.severity === 'error');
if (hasErrors || !vendor || !amount || !currency || uniqueIssues.length > 0) {
  validationStatus = 'needs_review';
}

return {
  expenseDate,
  vendor,
  invoiceNumber,
  description,
  amount,
  currency,
  taxAmount,
  subtotalAmount,
  category,
  validationStatus,
  validationIssues: JSON.stringify(uniqueIssues),
  sourceFileName: prev.fileName,
  idempotencyKey: prev.idempotencyKey
};

const duplicateCheck = $input.item.json;
const extracted = $('Validate & Sanitize Extraction').first().json;

const issues = JSON.parse(extracted.validationIssues || '[]');
let status = extracted.validationStatus;

const matched = duplicateCheck ? duplicateCheck.matchedCandidate : null;
if (matched && matched.id) {
  status = 'duplicate_suspected';
  issues.push({
    code: 'DUPLICATE_CANDIDATE',
    message: `Suspected duplicate of existing expense record ID ${matched.id} (${matched.vendor || 'Unknown Vendor'}, Invoice: ${matched.invoiceNumber || 'N/A'})`,
    severity: 'warning'
  });
}

// Generate standard CUID-like identifier for Postgres insert
const generatedId = 'exp_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return {
  id: generatedId,
  idempotencyKey: extracted.idempotencyKey,
  expenseDate: extracted.expenseDate,
  vendor: extracted.vendor,
  invoiceNumber: extracted.invoiceNumber,
  description: extracted.description,
  amount: extracted.amount,
  currency: extracted.currency,
  taxAmount: extracted.taxAmount,
  subtotalAmount: extracted.subtotalAmount,
  category: extracted.category,
  validationStatus: status,
  validationIssues: JSON.stringify(issues),
  sourceFileName: extracted.sourceFileName
};

const persistedRecord = $input.item.json;
if (!persistedRecord || !persistedRecord.id) {
  throw new Error('Database persistence failed to return a valid expense record.');
}

return {
  success: true,
  expense: persistedRecord
};
